import{_ as t}from"./chunks/icon.B7gRmRZx.js";import{_ as n,a as r,b as i,c as s,d as a,e as o,f as d,g as u,h as l,i as g,j as h,k as c,l as p}from"./chunks/0.1.12-193-neustart-de.DMY_PLph.js";import{_ as m,o as b,c as k,a3 as f}from"./chunks/framework.BlfGB29P.js";const D=JSON.parse('{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.82 · Uhrzeit aus einem Helfer in Rules","frontmatter":{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.82 · Uhrzeit aus einem Helfer in Rules"},"headers":[],"relativePath":"projects/logic-studio/index.md","filePath":"projects/logic-studio/index.md","lastUpdated":1794675960000}'),A={name:"projects/logic-studio/index.md"};function S(P,e,w,v,z,H){return b(),k("div",null,[...e[0]||(e[0]=[f('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+t+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – öffentliches Testupdate, 8. November 2026.</strong> Oberfläche und Dokumentation sind jetzt <strong>DE/EN/FR</strong>. Logic Studio ist eine eigene HA-App für grafische Funktionspläne, unabhängig von Grafik Visual Studio und Blocks for HA. Die React-Flow-Zeichenfläche mit eigenen Bausteinen, typgeprüften Verbindungen, Zoom und MiniMap bleibt erhalten; Bibliotheken und Lizenzen sind lokal enthalten.</p><div class="warning custom-block"><p class="custom-block-title">Testversion</p><p>Zuerst auf einem Testsystem installieren und vorher ein vollständiges Backup erstellen. Native Detailoptionen werden zunächst als JSON bearbeitet. Die App schreibt keine Automationen oder Skripte in HA zurück und schaltet keine Geräte. Erzeugte Ausgaben immer prüfen und selbst in HA installieren.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">GitHub-Testrelease und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Quellcode im Sammel-Repository</a></p><h2 id="ha-logic-studio-pro-0-1-82" tabindex="-1">HA Logic Studio Pro 0.1.82 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-82" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.82&quot;">​</a></h2><p>Der Rules-Assistent bietet <strong>Uhrzeit aus Helfer</strong> an. Wähle einen Home-Assistant-Helfer vom Typ <code>input_datetime</code> mit Uhrzeit. Der YAML-Export verwendet <code>trigger: time</code> und trägt die Entitäts-ID unter <code>at</code> ein. Wenn du die Uhrzeit am Helfer änderst, übernimmt Home Assistant den neuen Termin.</p><p>Im Live-Test auf dem Testsystem PC (64) wurde der Helfer von 17:27:27 auf 17:27:56 umgestellt. Zum ursprünglichen Termin blieb die Auslösung aus. Der Home-Assistant-Trace bestätigt die Ausführung um <strong>17:27:56</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.82" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.82 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-81" tabindex="-1">HA Logic Studio Pro 0.1.81 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-81" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.81&quot;">​</a></h2><p>Der Rules-Assistent bietet Sonnenaufgang und Sonnenuntergang als Auslöser an. Der optionale Zeitversatz wird in Minuten eingegeben. Negative Werte lösen vor dem Sonnenereignis aus, positive danach.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurde der YAML-Export in der installierten Version geprüft und validiert. 30 Minuten vor Sonnenaufgang ergaben <code>event: sunrise</code> und <code>offset: -1800</code>. 15 Minuten nach Sonnenuntergang ergaben <code>event: sunset</code> und <code>offset: 900</code>. Die YAML-Werte sind in Sekunden angegeben.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.81" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.81 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-80" tabindex="-1">HA Logic Studio Pro 0.1.80 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-80" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.80&quot;">​</a></h2><p>Der Rules-Assistent bietet den Auslöser <strong>Zahlenschwelle</strong> mit „Über“, „Unter“ oder beiden Grenzen für einen Bereich. Attribut und Mindestdauer sind optional. Der YAML-Export verwendet den nativen Home-Assistant-Auslöser <code>numeric_state</code>.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> erzeugte der installierte Rules-Editor für „Über 50“ den Eintrag <code>above: 50</code>. Im Live-Test des erzeugten YAMLs löste die Automation bei 51 einmal aus. Bei 65 und 49 blieb der Zähler bei 1. Erst beim erneuten Überschreiten mit 52 stieg der Zähler auf 2.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.80" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.80 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-79" tabindex="-1">HA Logic Studio Pro 0.1.79 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-79" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.79&quot;">​</a></h2><p>Die Importvorschau in Blocks JS zeigt pro Block, welche Home-Assistant-Entität zugeordnet werden muss oder welche Codeanpassung noch nötig ist. Feste ioBroker-IDs lassen sich direkt in der Vorschau einer HA-Entität zuordnen.</p><p>Mit dem Originalexport <code>test33.xml</code> wurden auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> der Zustandstrigger einem Sensor und der Schreibblock einem Zahlenhelfer zugeordnet. Im Testlauf simulierte Blocks JS Schreibvorgänge mit den Werten <code>21</code> und <code>20</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.79" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.79 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-78" tabindex="-1">HA Logic Studio Pro 0.1.78 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-78" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.78&quot;">​</a></h2><p>Unter <strong>Globale Skripte</strong> können JavaScript- und TypeScript-Projekte gespeicherte Skripte aus dem gleichnamigen Ordner auswählen. Der Dialog zeigt den Aufrufpfad für benannte Funktionen, die mit <code>export function</code> freigegeben wurden, etwa <code>shared.script_43.twice(21)</code>.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> rief je ein allgemeines JavaScript- und TypeScript-Projekt dieselbe globale TypeScript-Funktion auf. Testlauf und Runtime lieferten in beiden Projekten <code>42</code>. TypeScript markierte ein Argument mit falschem Typ in Zeile 2. Die Auswahl blieb nach dem Neuladen erhalten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.78" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.78 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-77" tabindex="-1">HA Logic Studio Pro 0.1.77 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-77" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.77&quot;">​</a></h2><p><strong>Typen prüfen</strong> prüft den TypeScript-Code und die Typen der Skript-API. Der Editor markiert fehlerhafte Zeilen. Ein Klick auf die Zeilennummer im Protokoll springt zur ursprünglichen Stelle. Testlauf und Runtime prüfen die Typen vor der Ausführung.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurden zwei absichtlich erzeugte Typfehler in Zeile 2 und 3 markiert. Nach der Korrektur lief der Testlauf erfolgreich. Beim Start des fehlerhaften Skripts meldete die Runtime Zeile 2.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.77" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.77 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-76" tabindex="-1">HA Logic Studio Pro 0.1.76 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-76" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.76&quot;">​</a></h2><p>In den JavaScript- und TypeScript-Editoren schlägt <code>ha.</code> Methoden der Skript-API vor. Die Liste zeigt Parameter und Rückgabetypen. Beim Schreiben eines Aufrufs hebt der Editor den aktuellen Parameter hervor.</p><p>Im Chrome-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurden die Tastaturauswahl in beiden Editoren und die Signaturen für <code>ha.readState</code>, <code>ha.callAction</code> und <code>ha.pause</code> geprüft.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.76" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.76 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-75" tabindex="-1">HA Logic Studio Pro 0.1.75 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-75" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.75&quot;">​</a></h2><p>Das Protokoll zeigt im Testlauf und in der Runtime bei zuordenbaren Fehlern die ursprüngliche JavaScript- oder TypeScript-Zeile an. Ein Klick auf die Zeilennummer springt im Editor zur betroffenen Stelle.</p><p>Auf dem <strong>Testsystem PC (64)</strong> meldeten beide Ausführungsarten den absichtlich ausgelösten Fehler in <strong>JavaScript-Zeile 3</strong> und <strong>TypeScript-Zeile 5</strong>. Die TypeScript-Zeilennummer blieb korrekt, obwohl beim Übersetzen eine Typdeklaration wegfiel.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.75" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.75 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-74" tabindex="-1">HA Logic Studio Pro 0.1.74 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-74" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.74&quot;">​</a></h2><p>Logic Studio Pro speichert die letzten 100 Runtime-Protokolleinträge pro Benutzer und Projekt. Auf dem Testsystem PC (64) blieb ein Eintrag nach einem Neustart der App mit demselben Zeitstempel abrufbar. Das Skript war dabei gestoppt. In einem anderen Projekt erschien der Eintrag nicht.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.74" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.74 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-73" tabindex="-1">HA Logic Studio Pro 0.1.73 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-73" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.73&quot;">​</a></h2><p>Beim Runtime-Test auf dem Testsystem PC (64) mit 0.1.72 startete der zweite Auslöser, bevor der erste abgeschlossen war. Beide liefen bis zum Ende. Ein gezielter Fehler stoppte das betroffene Skript. Das andere Skript verarbeitete anschließend einen dritten Auslöser erfolgreich.</p><p>Nach dem lokalen Update auf 0.1.73 wurde auf dem Testsystem PC (64) geprüft, dass die Home-Assistant-App-Seite „Experimentell“ und der Studio-Header „Interner Test“ nicht mehr anzeigen. Die drei Testprojekte wurden gelöscht.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.73" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.73 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-72" tabindex="-1">HA Logic Studio Pro 0.1.72 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-72" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.72&quot;">​</a></h2><p>Blocks JS übernimmt ioBroker-Skriptnachrichten mit Antwort und berechneten Zieladressen. Die Importvorschau zeigt am jeweiligen Block, welche Empfangsadresse und Antwortverarbeitung zu prüfen sind.</p><p>Auf dem Testsystem PC (64) setzte ein laufendes Blocks-JS-Skript die Zieladresse aus zwei Textteilen zusammen. Das zweite Skript protokollierte den Empfang, und der Antwortblock im Sender wurde ausgeführt. Danach wurden beide Testprojekte gelöscht und die temporäre Freigabe für <code>logic_studio_script_message</code> wieder entfernt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.72" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.72 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-71" tabindex="-1">HA Logic Studio Pro 0.1.71 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-71" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.71&quot;">​</a></h2><p>Der Schalter „Expertenmodus“ im Projektmenü speichert die Auswahl pro Home-Assistant-Benutzer. Er blendet erweiterte Werkzeuge ein, darunter Quelltext und Skript-API in JavaScript, Import und Codeausgabe in Blocks JS sowie Diagnose und Ausführung im Funktionsplan. Speichern, Abbrechen, Testlauf und Play sind in den dafür vorgesehenen Editoren direkt erreichbar.</p><p>Nach einem Vollbackup auf dem Testsystem PC (64) wurden diese drei Editoren geprüft. Die Auswahl blieb nach dem Neuladen erhalten. Anschließend wurde die ursprüngliche Einstellung wiederhergestellt und nach erneutem Neuladen bestätigt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.71" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.71 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-70" tabindex="-1">HA Logic Studio Pro 0.1.70 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-70" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.70&quot;">​</a></h2><p>Benutzerdefinierte Ordner lassen sich über das Stiftsymbol im Projektbaum umbenennen. Auf dem Testsystem PC (64) habe ich nach einem Vollbackup die Projektbaum-Exporte vor dem Umbenennen und nach dem Neuladen verglichen. Ordner-ID, Projektzuordnungen und Reihenfolge der beiden Projekte blieben erhalten. Danach habe ich den ursprünglichen Namen wiederhergestellt und nach erneutem Neuladen bestätigt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.70" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.70 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-69" tabindex="-1">HA Logic Studio Pro 0.1.69 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-69" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.69&quot;">​</a></h2><p>Der Rules-Assistent übernimmt einen Sprachwechsel im geöffneten Editor. Nach einem Vollbackup auf dem Testsystem PC (64) wurden im Chrome-Tabletformat (820 × 1180 px) beim Wechsel <strong>DE → EN → FR → DE</strong> Titel, Schritte und Auslöser in der jeweils gewählten Sprache angezeigt. Die Studio-Oberfläche und die App-Verwaltung in Home Assistant zeigten beide <strong>0.1.69</strong>. Der Server liest die angezeigte Version jetzt aus den Paketdaten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.69" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.69 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-68" tabindex="-1">HA Logic Studio Pro 0.1.68 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-68" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.68&quot;">​</a></h2><p>Der YAML-Export lädt die Datei direkt aus dem Editor herunter. Beim Doppeltest auf dem Testsystem PC (64) wurden zwei vollständige, bytegleiche YAML-Dateien erzeugt. Chrome meldete beim zweiten Export <strong>Unsicherer Download blockiert</strong>. Nach der manuellen Bestätigung mit <strong>Behalten</strong> lag auch die zweite Datei vollständig im Downloadordner.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.68" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.68 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-67" tabindex="-1">HA Logic Studio Pro 0.1.67 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-67" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.67&quot;">​</a></h2><p>Aktuelles öffentliches Testupdate. Vor dem Update ein Vollbackup erstellen und zuerst auf einem Testsystem prüfen.</p><p>„Datenpunkt vorhanden?“ und „Objekt-ID“ behalten beim Import die ioBroker-ID. Ordne sie im jeweiligen Block ausdrücklich einer HA-Entität zu. Beim Import einer JavaScript-Datei erkennt Blocks JS eingebettete Blockly-Daten auch dann, wenn weitere Kommentare folgen.</p><p>Unter <strong>Nötige Codeanpassungen</strong> erklärt die Importvorschau, wie sich nicht unterstützte Blöcke wie <code>exec</code> ersetzen lassen. Auf dem Testsystem PC (64) wurden nach einem Vollbackup XML- und JavaScript-Testdateien importiert und die neuen Zuordnungsfelder im Editor geprüft.</p><h3 id="wiederverbindung-nach-core-neustart" tabindex="-1">Wiederverbindung nach Core-Neustart <a class="header-anchor" href="#wiederverbindung-nach-core-neustart" aria-label="Permalink to &quot;Wiederverbindung nach Core-Neustart&quot;">​</a></h3><p>Auf dem Testsystem PC (64) wurde vor dem Test ein Vollbackup erstellt. Nach dem Neustart von Home Assistant Core stellte die Runtime die Verbindung 31 Sekunden nach der Trennung wieder her. Derselbe JavaScript-Skriptlauf empfing anschließend den Wechsel des Testhelfers von <code>off</code> auf <code>on</code> und das benutzerdefinierte HA-Ereignis <code>logic_studio_runtime_test</code> samt Testdaten.</p><h3 id="ordnerwechsel-und-reihenfolge-nach-neuladen" tabindex="-1">Ordnerwechsel und Reihenfolge nach Neuladen <a class="header-anchor" href="#ordnerwechsel-und-reihenfolge-nach-neuladen" aria-label="Permalink to &quot;Ordnerwechsel und Reihenfolge nach Neuladen&quot;">​</a></h3><p>Auf dem Testsystem PC (64) wurden nach einem Vollbackup zwei Testskripte per Drag-and-drop in einen anderen Ordner verschoben. Nach dem Speichern der Sortierung und dem Neuladen von Logic Studio Pro waren beide Skripte weiterhin im Zielordner und standen in der gespeicherten Reihenfolge.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.67" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.67 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-66" tabindex="-1">HA Logic Studio Pro 0.1.66 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-66" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.66&quot;">​</a></h2><p>Aktiviere im Funktionsplan <strong>Zähler und Merker speichern</strong> und speichere das Projekt. CTU, CTD, CTUD, RS und SR können ihre Werte nach einem App-Neustart wiederherstellen.</p><p>Der Blocks-JS-Importbericht weist berechnete ioBroker-IDs separat aus. Ordne im importierten Block unter <strong>ID-Zuordnung (JSON)</strong> jede mögliche ioBroker-ID einer HA-Entität zu.</p><p>Auf dem Testsystem PC (64) behielten der CTU-Zähler und der RS-Merker nach einem App-Neustart die Werte <code>1</code> und <code>true</code>.</p><p>Im Live-Test auf dem Testsystem PC (64) berechnete das importierte Blocks-JS-Skript die ioBroker-ID <code>zigbee.0.sensor</code>. Über <strong>ID-Zuordnung (JSON)</strong> las es den HA-Testhelfer <code>input_boolean.logic_studio_runtime_test</code>. Zwei Starts über <strong>Play</strong> ergaben im Runtime-Protokoll <code>false</code> bei ausgeschaltetem und <code>true</code> bei eingeschaltetem Helfer.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.66" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.66 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-65" tabindex="-1">HA Logic Studio Pro 0.1.65 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-65" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.65&quot;">​</a></h2><h3 id="autostart-simulation-und-iobroker-import" tabindex="-1">Autostart, Simulation und ioBroker-Import <a class="header-anchor" href="#autostart-simulation-und-iobroker-import" aria-label="Permalink to &quot;Autostart, Simulation und ioBroker-Import&quot;">​</a></h3><p>JavaScript, TypeScript und Funktionspläne können beim Start der App ausgeführt werden. Speichere dafür die Option <strong>Beim Start der App ausführen</strong> im Projekt. Die Simulation bietet Haltepunkte und Einzelschritt. Beim automatischen Anordnen bleiben angeheftete Bausteine stehen. Blocks JS zeigt beim ioBroker-Import nicht unterstützte Blöcke und feste IDs zur Zuordnung.</p><p>Auf dem Testsystem PC (64) startete das gespeicherte JavaScript-Testprojekt nach einem Neustart der App automatisch. Geprüft wurden außerdem ein Haltepunkt mit Einzelschritt sowie die ioBroker-Importvorschau mit einer festen ID.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.65" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.65 · GitHub / ZIP</a></p><h2 id="ha-logic-studio-pro-0-1-62" tabindex="-1">HA Logic Studio Pro 0.1.62 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-62" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.62&quot;">​</a></h2><p>HA Logic Studio Pro ist eine eigenständige Home-Assistant-App im UGSo-Sammelrepository. Sie baut auf Logic Studio auf und greift Erfahrungen aus der Arbeit mit ioBroker auf.</p><p><strong>Verfügbare Funktionen</strong></p><ul><li><strong>Funktionsplan:</strong> Bausteine verbinden, Signale an den Eingängen anzeigen und den Plan simulieren. Die Ausführung auf dem HA-Server kann auf Änderungen reagieren oder in einem festen Zyklus laufen.</li><li><strong>Regeln und Blocks A:</strong> Automationen visuell erstellen und als HA-YAML ausgeben.</li><li><strong>Blocks JS, JavaScript und TypeScript:</strong> Logik bearbeiten, mit simulierten Werten testen und auf dem HA-Server ausführen.</li><li><strong>HA-YAML:</strong> Automationen und Skripte bearbeiten, prüfen und exportieren.</li><li><strong>Projektverwaltung:</strong> Projekte und Ordner pro HA-Benutzer auf dem Server speichern.</li><li><strong>Sprachwahl:</strong> Die Editoren stehen auf Deutsch, Englisch und Französisch zur Verfügung.</li></ul><p><strong>0.1.62</strong> ergänzte die unten beschriebenen Rules-Funktionen.</p><h3 id="erweiterte-rules-und-live-test-auf-dem-testsystem-pc-64" tabindex="-1">Erweiterte Rules und Live-Test auf dem Testsystem PC (64) <a class="header-anchor" href="#erweiterte-rules-und-live-test-auf-dem-testsystem-pc-64" aria-label="Permalink to &quot;Erweiterte Rules und Live-Test auf dem Testsystem PC (64)&quot;">​</a></h3><p>Zustandsauslöser unterstützen Von/Nach, ein Attribut und eine Mindestdauer. Bedingungen prüfen Zustände und Attribute sowie numerische Grenzen. DANN und SONST unterstützen einen HA-Aktionswähler mit JSON-Parametern und separate Verzögerungsschritte.</p><p>Der Editor und der Aktionswähler wurden lokal im Browser geprüft. Nach einem Vollbackup lief die erzeugte YAML direkt in Home Assistant auf dem Testsystem PC (64). Ein kurzer Impuls löste nichts aus. Nach drei Sekunden Zustandsdauer lief DANN. Ein Wechsel des Anzeigenamens löste SONST aus. Beide Traces bestätigten zwei Sekunden Verzögerung und den erwarteten Textwert. Die Testautomation und beide Helfer wurden entfernt.</p><p>Die neuen Bausteine werden als HA-YAML ausgegeben. Rules → JS meldet, wenn ein Baustein die Konvertierung verhindert.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.62" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.62 · GitHub / ZIP</a></p><h3 id="yaml-export-und-live-test-auf-dem-testsystem-pc-64" tabindex="-1">YAML-Export und Live-Test auf dem Testsystem PC (64) <a class="header-anchor" href="#yaml-export-und-live-test-auf-dem-testsystem-pc-64" aria-label="Permalink to &quot;YAML-Export und Live-Test auf dem Testsystem PC (64)&quot;">​</a></h3><p>Der Rules-Export schützt Zustände wie <code>on</code> und <code>off</code> vor der Umwandlung in YAML-Wahrheitswerte. Die korrigierte Automation wurde direkt in Home Assistant auf dem Testsystem PC (64) mit Testhelfern ausgeführt.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Auslöser</th><th>Bedingung</th><th>Ergebnis laut HA-Trace</th></tr></thead><tbody><tr><td>Zustandswechsel</td><td>ODER erfüllt</td><td>Beide DANN-Aktionen</td></tr><tr><td>Zustandswechsel</td><td>UND nicht erfüllt</td><td>Beide SONST-Aktionen</td></tr><tr><td>HA-Ereignis</td><td>NICHT erfüllt</td><td>Beide DANN-Aktionen</td></tr><tr><td>Uhrzeit 20:26</td><td>NICHT nicht erfüllt</td><td>Beide SONST-Aktionen</td></tr></tbody></table></div><p>Vor dem Test wurde ein Vollbackup erstellt. Die Testautomation und alle drei Testhelfer wurden danach entfernt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.61" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.61 · GitHub / ZIP</a></p><h3 id="rules-kompakte-leiste-und-mehrere-ausloser" tabindex="-1">Rules: kompakte Leiste und mehrere Auslöser <a class="header-anchor" href="#rules-kompakte-leiste-und-mehrere-ausloser" aria-label="Permalink to &quot;Rules: kompakte Leiste und mehrere Auslöser&quot;">​</a></h3><p>Links zeigt der Editor eine kompakte Liste mit Icons. Eine Regel kann Zustandswechsel, tägliche Uhrzeit und HA-Ereignisse kombinieren. Bedingungen unterstützen UND, ODER und NICHT. In DANN und SONST laufen mehrere Aktionen in der eingetragenen Reihenfolge.</p><p>Auf dem Testsystem PC (64) wurde eine bestehende Regel mit drei Auslösern, zwei Bedingungen und zwei Aktionen pro Zweig geprüft. Die YAML-Vorschau zeigte die erwartete Struktur. Im Studio-Testlauf führten alle drei simulierten Auslöser bei erfüllter ODER-Bedingung beide DANN-Aktionen aus. Bei nicht erfüllter UND-Bedingung liefen beide SONST-Aktionen in der festgelegten Reihenfolge. Es wurden keine echten Geräte geschaltet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.60" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.60 · GitHub / ZIP</a></p><p><img src="'+n+'" alt="Rules-Editor auf dem Testsystem PC (64) mit kompakter Leiste und beiden Aktionszweigen"></p><h3 id="regeln-mit-dem-assistenten-erstellen" tabindex="-1">Regeln mit dem Assistenten erstellen <a class="header-anchor" href="#regeln-mit-dem-assistenten-erstellen" aria-label="Permalink to &quot;Regeln mit dem Assistenten erstellen&quot;">​</a></h3><p>Wähle <strong>Regeln → Assistent</strong>. Der Dialog führt durch <strong>Auslöser → Bedingungen → Aktionen → Übersicht</strong>. Eine Regel kann auf einen Zustandswechsel, eine tägliche Uhrzeit in der HA-Zeitzone oder ein HA-Ereignis reagieren. Bedingungen und der SONST-Zweig sind optional. In der Übersicht siehst du die YAML-Vorschau. <strong>Übernehmen</strong> überträgt den Entwurf in den Editor; erst <strong>Speichern</strong> sichert ihn dauerhaft. Bestehende Regeln lassen sich weiterhin bearbeiten und als JavaScript oder HA-YAML öffnen.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.59" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.59 · GitHub / ZIP</a></p><p>Am 12. November 2026 wurden alle drei Auslöser direkt in Home Assistant auf dem Testsystem PC (64) geprüft. Ein Zustandswechsel von Aus auf Ein, die tägliche Uhrzeit um 19:38 Uhr (HA-Ortszeit) und das Ereignis <code>rules_live_0159_event</code> schalteten den Testausgang jeweils auf Ein. Vor dem Test wurde ein Vollbackup erstellt. Anschließend wurden die drei Testautomationen und beide Testhelfer entfernt.</p><p><img src="'+r+`" alt="Home Assistant zeigt die letzte Ausführung aller drei Rules-Testautomationen und den eingeschalteten Testausgang"></p><h3 id="was-seit-0-1-12-neu-ist" tabindex="-1">Was seit 0.1.12 neu ist <a class="header-anchor" href="#was-seit-0-1-12-neu-ist" aria-label="Permalink to &quot;Was seit 0.1.12 neu ist&quot;">​</a></h3><ul><li><strong>Projektbaum und Editoren:</strong> Projekte und Ordner werden pro HA-Benutzer serverseitig gespeichert. Vorhandene Browserprojekte können beim ersten Start aus dem bisherigen Browser übernommen werden. JavaScript und TypeScript haben Syntaxfarben, Zeilennummern und eigene Werkzeugleisten. Icons und Farben stimmen zwischen Projektauswahl, Baum und Filtern überein. Blocks A und Blocks JS haben getrennte Filter. Die automatisch bemessene Projektspalte bleibt per Anfasser verstellbar.</li><li><strong>Blocks A und Blocks JS:</strong> Blocks A nutzt den integrierten Katalog von Blocks for HA. Blocks JS hat eine eigene JavaScript-Palette. Blocks A exportiert HA-Automationen als YAML. Blocks JS erzeugt JavaScript für Testlauf und Runtime. Beim ioBroker-Import bleiben unbekannte Blöcke als Platzhalter sichtbar und verhindern die Codeausgabe, bis sie ersetzt sind. ioBroker-Objekt-IDs durch passende HA-Entitäts-IDs ersetzen.</li><li><strong>Funktionsplan:</strong> Simulation, Zeitschritt von einer Sekunde und Zurücksetzen liegen als Icons in der oberen Leiste. Ausgabeformat und Vorschau sind rechts angeordnet. Verbindungen lassen sich am Zieleingang umhängen, Signalwerte erscheinen direkt am Eingang.</li><li><strong>Server-Runtime:</strong> Play startet JavaScript, transpiliertes TypeScript oder Blocks JS auf dem HA-Server. Stopp und Neustart sind im Editor verfügbar. Status und Runtime-Protokoll bleiben beim Browserwechsel abrufbar. Der separate <strong>Testlauf</strong> verwendet simulierte Zustände und Ereignisse. HA-YAML-Skripte und -Automationen werden exportiert und anschließend in Home Assistant ausgeführt.</li></ul><h3 id="live-runtime-einrichten" tabindex="-1">Live-Runtime einrichten <a class="header-anchor" href="#live-runtime-einrichten" aria-label="Permalink to &quot;Live-Runtime einrichten&quot;">​</a></h3><p>In <strong>Einstellungen → Apps → HA Logic Studio Pro → Konfiguration</strong> die benötigten Einträge setzen, speichern und die App neu starten. Die Listen sind anfangs leer. Beispiel für einen eigens angelegten Testhelfer:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_read_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_write_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.logic_studio_runtime_test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_runtime_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Eine Schreibfreigabe erlaubt auch das Lesen. <code>ha.readState</code> und <code>ha.readAttribute</code> liefern die zuletzt von HA bestätigten Werte. <code>ha.onState</code>, <code>ha.onAttribute</code> und <code>ha.onEvent</code> reagieren auf freigegebene Änderungen und Ereignisse. <code>ha.callAction</code> unterstützt Schaltaktionen, Werte für Zahlen-, Text- und Auswahlhelfer sowie Taster mit genau einem freigegebenen Ziel. <code>ha.schedule</code> verarbeitet Zeitmuster und feste Uhrzeiten mit optionalen Wochentagen in der HA-Zeitzone.</p><p>Nach einem App-Neustart müssen Skripte erneut gestartet werden. Bei einer Verbindungsunterbrechung oder abgelehnten Aktion hält die Runtime das Skript an und protokolliert den Fehler. Astro-Auslöser und automatische Wiederverbindung sind offen.</p><p><strong>Geprüft auf dem Testsystem PC (64) mit HA 2026.11.1:</strong> Live-Zustand und Attribut gelesen, Testhelfer per Zeitplan eingeschaltet und per echtem HA-Ereignis ausgeschaltet. Beide Zustandswechsel wurden gemeldet. Ein importierter Blocks-JS-Zeitplan lief alle zwei Sekunden. Zuvor wurden Start, Stopp, Neustart und der Weiterlauf nach Verlassen der Studio-Seite mit JavaScript und TypeScript geprüft.</p><h3 id="skripte-und-automationen-steuern" tabindex="-1">Skripte und Automationen steuern <a class="header-anchor" href="#skripte-und-automationen-steuern" aria-label="Permalink to &quot;Skripte und Automationen steuern&quot;">​</a></h3><p>Unter <strong>Blocks JS → System</strong> wählst du mit <strong>Skript oder Automation auswählen</strong> eine Home-Assistant-Entität aus und verbindest den Block mit <strong>Steuern</strong>. Skripte lassen sich starten oder stoppen. Automationen lassen sich aktivieren, deaktivieren oder einmal auslösen. Beim Auslösen ist <strong>Bedingungen prüfen</strong> standardmäßig aktiv. Wenn du die Option abwählst, überspringt Home Assistant die Bedingungen. Für die Live-Ausführung muss die Zielentität unter <code>runtime_write_entities</code> freigegeben sein.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.58" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.58 · GitHub und ZIP</a></p><h3 id="funktionen-und-iobroker-import" tabindex="-1">Funktionen und ioBroker-Import <a class="header-anchor" href="#funktionen-und-iobroker-import" aria-label="Permalink to &quot;Funktionen und ioBroker-Import&quot;">​</a></h3><p>Unter <strong>Blocks JS → Funktionen</strong> gibt es zwei JavaScript-Funktionsblöcke mit und ohne Rückgabewert. Über das Zahnrad legst du Parameter fest. Über <strong>…</strong> bearbeitest du den Code. Nach dem Anlegen einer Definition erscheint der passende Aufrufblock in der Palette.</p><p>Der ioBroker-Import übernimmt Definitionen, Aufrufe, Parameter und JavaScript-Code. Passe ioBroker-spezifische API-Aufrufe an die HA-Runtime an und ordne importierte Objekt-IDs explizit HA-Entitäten zu.</p><h3 id="verlauf-abfragen" tabindex="-1">Verlauf abfragen <a class="header-anchor" href="#verlauf-abfragen" aria-label="Permalink to &quot;Verlauf abfragen&quot;">​</a></h3><p>Unter <strong>Blocks JS → Sendto → Verlauf abfragen</strong> liest du aufgezeichnete Zustände aus dem HA-Recorder. Ohne Zeitraum gilt der aktuelle Tag in der HA-Zeitzone. Der Ergebnisblock liefert Einträge mit Zeitstempel und Wert. Beim ioBroker-Import bleiben Zeitraum, Aggregation, Schrittweite und Anzahl erhalten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.57" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.57 · GitHub und ZIP</a></p><h3 id="_0-1-29-·-manuelles-speichern-und-blocks-editoren" tabindex="-1">0.1.29 · Manuelles Speichern und Blocks-Editoren <a class="header-anchor" href="#_0-1-29-·-manuelles-speichern-und-blocks-editoren" aria-label="Permalink to &quot;0.1.29 · Manuelles Speichern und Blocks-Editoren&quot;">​</a></h3><p>Alle Editoren übernehmen Änderungen erst mit <strong>Speichern</strong>. <strong>Abbrechen</strong> lädt den letzten gespeicherten Stand oder verwirft ein neues Projekt. Bei ungespeicherten Änderungen sind <strong>Play</strong> und <strong>Neustart</strong> gesperrt. Ein laufendes Skript lässt sich weiterhin stoppen. Blocks A öffnet die Entitätsauswahl direkt am Blockfeld. Blocks JS bietet eine an ioBroker orientierte Palette mit HA-Entitäten, HA-Aktionen und Auslösern ohne Jinja.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.29" target="_blank" rel="noreferrer">Testupdate und ZIP</a></p><h3 id="_0-1-28-·-ubersetzungen-in-den-editoren" tabindex="-1">0.1.28 · Übersetzungen in den Editoren <a class="header-anchor" href="#_0-1-28-·-ubersetzungen-in-den-editoren" aria-label="Permalink to &quot;0.1.28 · Übersetzungen in den Editoren&quot;">​</a></h3><p>Version <strong>0.1.28</strong> ergänzt die Übersetzungen für Regeln, Blocks A, Blocks JS, JavaScript, TypeScript und HA-YAML. Die Sprachwahl gilt auch für den Funktionsplan. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.28" target="_blank" rel="noreferrer">Testupdate und ZIP</a></p><p>Auf dem Testsystem PC (64) wurden die Werkzeugleisten von Funktionsplan, Regeln, Blocks A, Blocks JS, JavaScript, TypeScript, HA-Automation und HA-Skript im Browser in allen drei Sprachen geprüft. Zusätzlich wurde der französische Dialog für Codebeispiele geprüft.</p><p>Für die Installation im App-Store des UGSo-Sammelrepositories <strong>HA Logic Studio Pro</strong> auswählen. Bei einer bestehenden GitHub-Installation nach Updates suchen und <strong>HA Logic Studio Pro → Aktualisieren</strong> wählen. Mit <strong>DE</strong>, <strong>EN</strong> und <strong>FR</strong> oben in der Projektleiste wechselt die Sprache der Editoren.</p><h3 id="_0-1-26-·-fbd-runtime" tabindex="-1">0.1.26 · FBD Runtime <a class="header-anchor" href="#_0-1-26-·-fbd-runtime" aria-label="Permalink to &quot;0.1.26 · FBD Runtime&quot;">​</a></h3><p>Funktionsplan direkt über <strong>Play</strong> auf dem HA-Server starten. <strong>Automatisch</strong> reagiert auf Änderungen der freigegebenen Zustände und Attribute; <strong>Fester Zyklus</strong> wertet den Plan alle 100 bis 60.000 ms aus. Simulation und YAML-Ausgabe bleiben separat. <strong>Speichern</strong> übernimmt den Entwurf, <strong>Abbrechen</strong> lädt den letzten gespeicherten Stand. Die Werkzeugleiste ist in DE/EN/FR verfügbar.</p><p>Auf dem Testsystem PC (64) schaltete der Automatikstart den Testhelfer ein; der 200-ms-Zyklus schaltete ihn wieder aus. Stopp und das Verwerfen einer ungespeicherten Änderung wurden ebenfalls geprüft. Die Reaktion auf Eingangsänderungen wurde zusätzlich lokal für beide Betriebsarten getestet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.26" target="_blank" rel="noreferrer">GitHub-Testupdate und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_logic_studio_pro" target="_blank" rel="noreferrer">App im Sammelrepository</a></p><h2 id="testinstallation-aus-github" tabindex="-1">Testinstallation aus GitHub <a class="header-anchor" href="#testinstallation-aus-github" aria-label="Permalink to &quot;Testinstallation aus GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Repository in Home Assistant hinzufügen"></a></p><ol><li>In <strong>Einstellungen → Apps → App-Store → Repositorys</strong> die folgende Adresse eintragen. Ist „UGSo HA Apps“ schon eingerichtet, nur nach Updates suchen.</li><li><strong>UGSo Logic Studio</strong> auswählen und installieren. Falls experimentelle Apps ausgeblendet sind, im HA-Profil den erweiterten Modus aktivieren.</li><li>Starten und die Benutzeroberfläche öffnen. Unterstützt werden <strong>HA OS/Supervised</strong>, <strong>amd64 und aarch64</strong>. Der erste Container-Build kann einige Minuten dauern. Dies ist kein HACS-/Marketplace-Frontend-Paket.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Vorhandene lokale Testinstallation erhalten:</strong> GitHub- und lokale App haben verschiedene Repository-IDs und getrennte Daten. Den alten Plan über <strong>Projekt</strong> als JSON exportieren und in der GitHub-App über <strong>Öffnen</strong> importieren. Es gibt keine automatische Migration oder Deinstallation. Projekt und Paletteinstellungen der jeweiligen App bleiben unter <code>/data</code> gespeichert.</p><p><strong>Bestehende GitHub-App aktualisieren:</strong> Vorher sichern, in der App-Verwaltung nach Updates suchen und <strong>UGSo Logic Studio → Aktualisieren</strong> wählen. Die App bleibt installiert; <code>/data</code>, Entity-IDs und bestehende Pläne werden nicht ersetzt. Nicht deinstallieren oder die App-ID wechseln. Auf dem Testsystem PC (64) blieben Originalplan, Favoriten, zuletzt benutzte Bausteine und eingeklappte Bereiche nach dem Update erhalten.</p><h2 id="sprache-werkzeugleiste-und-dokumentation" tabindex="-1">Sprache, Werkzeugleiste und Dokumentation <a class="header-anchor" href="#sprache-werkzeugleiste-und-dokumentation" aria-label="Permalink to &quot;Sprache, Werkzeugleiste und Dokumentation&quot;">​</a></h2><p>Oben <strong>Sprache → Deutsch / English / Français</strong> wählen. Menüs, Bausteinbeschreibungen, Entitätsauswahl sowie Import-/Exportdialoge wechseln ohne Neuladen. Die Auswahl wird mit den Browser-/App-Einstellungen gespeichert. <strong>Eigene Namen, Entitäts-IDs, Werte, Anschlussbezeichnungen und erzeugter YAML-/JavaScript-Code werden nicht übersetzt.</strong></p><p><strong>Dokumentation</strong> rechts zeigt die tatsächlich unterstützten Tastenkürzel und bei ausgewähltem Baustein dessen Beschreibung sowie Ein-/Ausgänge. <strong>Strg+Z / Strg+Y</strong>: Rückgängig/Wiederholen; <strong>Entf</strong>: Auswahl löschen; <strong>Esc</strong>: Verbindung abbrechen/Menü schließen. Anschlüsse lassen sich mit Tab und Enter/Leertaste auswählen und verbinden. Debugger-Befehle des ioBroker-Referenzeditors werden nicht als verfügbare Funktionen dargestellt.</p><p>Die Werkzeugleiste gruppiert <strong>Rückgängig/Wiederholen → Projekt → Simulation → Ausgabe</strong>. Die drei Simulationsbuttons sind gleich groß und einzeln erkennbar. Das Projektmenü enthält zusätzlich <strong>Neues Projekt</strong> und <strong>Beispiel laden</strong>. Die Entitätsauswahl öffnet über das Icon <strong>neben HA-Entity-ID</strong> in den Eigenschaften von STATE_IN/STATE_OUT; der bisherige obere Auswahlbutton entfällt.</p><p><img src="`+i+'" alt="Deutsche Dokumentationsansicht auf dem Testsystem PC (64) mit unverändertem Plan"></p><p><img src="'+s+'" alt="Englische Dokumentationsansicht desselben Plans auf dem Testsystem PC (64)"></p><p><img src="'+a+'" alt="Französische Dokumentationsansicht desselben Plans auf dem Testsystem PC (64)"></p><h2 id="zwei-arten-von-planen" tabindex="-1">Zwei Arten von Plänen <a class="header-anchor" href="#zwei-arten-von-planen" aria-label="Permalink to &quot;Zwei Arten von Plänen&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Plan</th><th>Zweck und Ausgabe</th></tr></thead><tbody><tr><td>Wertplan</td><td>Typisierte Ein-/Ausgänge, Logik, Mathematik, Auswahl sowie Speicher, Flanken, Timer und Zähler. 33 implementierte Typen; weitere Referenztypen sind als Vorlagen gekennzeichnet. Ausgabe als HA-Automation, HA-Skript oder JavaScript-Funktion mit Host-Schnittstelle.</td></tr><tr><td>Nativer HA-Ablauf</td><td>Automationen, Skripte und Blueprints importieren und als verschachtelte Bausteine bearbeiten. 53 zusätzliche HA-Typen für Auslöser, Bedingungen, Zweige, Schleifen, Warteaktionen, Variablen und Blueprint-Eingaben. Ausgabe ausschließlich als native HA-YAML.</td></tr></tbody></table></div><p>Wertpläne können mit Demo-/Momentaufnahmewerten simuliert werden. Persistente Wertbausteine benötigen die dokumentierten HA-Texthelfer bzw. einen JavaScript-Speicher-Host. Native HA-Abläufe werden im Editor weder ausgeführt noch automatisch in JavaScript umgerechnet. Die JavaScript-Ausgabe ist kein ioBroker-Skript.</p><h2 id="verbindungen-ziehen-und-miniubersicht" tabindex="-1">Verbindungen ziehen und Miniübersicht <a class="header-anchor" href="#verbindungen-ziehen-und-miniubersicht" aria-label="Permalink to &quot;Verbindungen ziehen und Miniübersicht&quot;">​</a></h2><p>Am farbigen Anschluss die Maustaste gedrückt halten, zum passenden Gegenanschluss ziehen und loslassen. Der Cursor wird zum Kreuz; eine Leitungsvorschau folgt der Maus. Passende Ziele werden grün, unpassende oder belegte Eingänge rot markiert. Auch vom Eingang zurück zum Ausgang ziehen ist möglich. <strong>Esc</strong> oder Loslassen auf freier Fläche bricht ab; <strong>Rückgängig</strong> nimmt eine erstellte Leitung zurück.</p><p><strong>BOOL verbindet nur mit BOOL.</strong> Gleiche Signaltypen passen zueinander; <code>INT → REAL</code> ist zusätzlich erlaubt. Explizite <code>ANY</code>-Anschlüsse sind universell. Zahlen und Texte werden nicht stillschweigend zu BOOL umgedeutet. Pro Eingang ist genau eine Leitung erlaubt; falsche Typen, gleiche Anschlussseiten, Selbstverbindungen und Rückkopplungen werden abgewiesen. Eine Fehlermeldung erklärt den Grund. Für die Tastatur Ausgang per Tab/Enter auswählen, anschließend Eingang und Enter.</p><p><img src="'+o+'" alt="Auf dem Testsystem PC (64) erfolgreich mit der Maus verbundene BOOL-Anschlüsse"></p><p><img src="'+d+'" alt="STRING nach BOOL wird mit verständlichem Typfehler abgewiesen"></p><p>Rechts unten zeigt die <strong>MiniMap</strong> farbige Bausteinpositionen und den sichtbaren Ausschnitt. In der MiniMap ziehen zum Navigieren und das Mausrad zum Zoomen verwenden. Auf der freien Zeichenfläche ziehen verschiebt den Ausschnitt; <strong>+/−</strong> ändern den Zoom, <strong>Alles anzeigen</strong> passt alle Bausteine ein. Bausteine am Kopf verschieben. Der Herkunftslink <strong>React Flow</strong> bleibt unten rechts sichtbar. Seit 0.1.8 läuft die Bibliothek tatsächlich im Editor; Fachlogik, Typprüfung und Exporte bleiben eigenständige Logic-Studio-Funktionen.</p><p><img src="'+u+'" alt="React-Flow-Zeichenfläche mit erhaltenem Originalplan und MiniMap auf dem Testsystem PC (64)"></p><p><img src="'+l+'" alt="Lokaler React-Flow-Test mit typisierten Bausteinen"></p><p>Die folgenden Bilder dokumentieren zusätzlich die vorherigen Tests mit 0.1.7.</p><p><img src="'+g+'" alt="Miniübersicht mit Bausteinpositionen und sichtbarem Ausschnitt auf dem Testsystem PC (64)"></p><h2 id="import-und-bearbeitung" tabindex="-1">Import und Bearbeitung <a class="header-anchor" href="#import-und-bearbeitung" aria-label="Permalink to &quot;Import und Bearbeitung&quot;">​</a></h2><p><strong>HA importieren</strong> öffnen, Automationen/Skripte/Blueprints auswählen und <strong>Aus HA einlesen</strong>, eine YAML-/JSON-Datei oder eingefügten Text verwenden. Eintrag und Vorschau prüfen, dann <strong>Import übernehmen</strong>. Vorher den eigenen Plan als JSON sichern; zusätzlich entstehen Projekt- und Quelldateisicherungen.</p><p>Der HA-Konfigurationsordner ist <strong>schreibgeschützt</strong> eingebunden. Gelesen werden <code>automations.yaml</code>, <code>scripts.yaml</code> und Blueprint-Dateien. Vor dem Parsen kopiert die App Quellen unter <code>/data/ha-source-backups/&lt;Zeitstempel&gt;/</code> mit ursprünglichem Namen. <code>secrets.yaml</code> wird nicht geöffnet; <code>!secret</code> und <code>!include</code> bleiben unaufgelöst. Bei ausgelagerten Include-Dateien die tatsächliche Datei selbst importieren.</p><p>Orange <strong>FLOW</strong>-Leitungen bilden Reihenfolge und Zweige ab: Zweigausgang → <strong>DO</strong>, anschließend <strong>NEXT → DO</strong>. Gelbe <strong>VALUE/REF</strong>-Leitungen zeigen Blueprint-Parameter und deren <code>!input</code>-Verwendung. Eigenschaften enthalten HA-Konfiguration und Zweigpfade als JSON. Parameter-/Feldschlüssel müssen eindeutig sein. Unbekannte Abschnitte bleiben als <strong>YAML_ORIGINAL</strong> erhalten; fehlende Verbindungen können den Export sperren.</p><p><img src="'+h+'" alt="Importvorschau vorhandener HA-Blueprints"></p><p>Das <strong>⋮-Menü</strong> jedes Bausteins bietet <strong>Eigenschaften, Duplizieren und Löschen</strong>. Duplizieren übernimmt Eigenschaften ohne Leitungen. Löschen entfernt zugehörige Leitungen; <strong>Rückgängig</strong> stellt sie wieder her. Suche, Favoriten und zuletzt benutzte Bausteine erleichtern die Auswahl.</p><p><img src="'+c+'" alt="Drei-Punkte-Menü im Funktionsplan"></p><h2 id="prufstand-und-grenzen" tabindex="-1">Prüfstand und Grenzen <a class="header-anchor" href="#prufstand-und-grenzen" aria-label="Permalink to &quot;Prüfstand und Grenzen&quot;">​</a></h2><p><strong>0.1.12 auf dem Testsystem PC (64) / HA Core 2026.10.4:</strong> Nach Vollbackup die lokale App von 0.1.8 aktualisiert. DE/EN/FR, Dokumentationsansicht und reale Entitätsauswahl erfolgreich geprüft. Französisch blieb nach Browser-Neuladen, App-Neustart und erneutem Laden des gespeicherten App-Projekts erhalten; abschließend wieder Deutsch eingestellt. Der Vergleich der Projektdateien zeigt <strong>nur die neue Versionsnummer</strong>, alle fünf Bausteine, drei Verbindungen, Namen, Werte und Positionen sind identisch. Der erzeugte YAML-Code ist in EN und FR identisch. Keine Geräte geschaltet. <strong>31 Node- und neun Python-Tests</strong> bestanden. Die folgenden älteren Berichte bleiben als Historie erhalten.</p><p><img src="'+p+'" alt="Deutsch nach erfolgreichem App-Neustart auf dem Testsystem PC (64)"></p><p><strong>0.1.8 auf dem Testsystem PC (64) / HA Core 2026.10.4:</strong> Bestehende lokale App nach Vollbackup aktualisiert. BOOL-Verbindungen per Maus, STRING→BOOL-Abweisung, belegte Eingänge, Verschieben/Rückgängig, Duplizieren, Zoom und MiniMap bestanden. Die Entitätsauswahl liest HA-Entitäten; ein verschachteltes Skript mit If/Then/Else, Delay und Stop wurde importiert und strukturerhaltend ausgegeben. Danach Originalplan wiederhergestellt und nach Neuladen verglichen: <strong>alle IDs, Positionen, Parameter und drei Leitungen unverändert</strong>, ebenso Favoriten, zuletzt benutzt und eingeklappte Kategorien. Keine Geräte geschaltet. Docker-Build und Container-HTTP-Test erfolgreich; <strong>29 Node- und acht Python-Tests</strong> bestanden. Bilder zeigen die deutsche Oberfläche. Hell-/Dunkel-Wechsel wurde in diesem Schritt nicht erneut manuell geprüft.</p><p>Der Funktionsstand <strong>0.1.5</strong> wurde auf <strong>Testsystem PC (64) / HA Core 2026.10.4</strong> geprüft: echter Blueprint-Import, Automation-/Skript-/Blueprint-Beispiele, inhaltlich gleiche YAML-Ausgabe und Menüaktionen. <strong>0.1.6</strong> ist dessen erste öffentliche Paketierung. 22 Node- und acht Python-Tests prüfen unter anderem Export, Persistenz, verschachtelte Abläufe und sicheren Quelldateiimport; die GitHub-Prüfung baut zusätzlich den Container.</p><p><strong>0.1.7 auf dem Testsystem PC (64) / HA Core 2026.10.4:</strong> Echter Maus-Ziehtest für BOOL → BOOL und die Gegenrichtung bestanden. STRING → BOOL und ein bereits belegter Eingang wurden abgewiesen. Miniübersicht, Klicknavigation und Pos1 geprüft. Nach dem Test wurde der Originalplan wiederhergestellt und mit der Sicherung verglichen: <strong>fünf Bausteine, drei Leitungen und alle Paletteinstellungen erhalten</strong>, einschließlich nach dem lokalen Update auf 0.1.7. Vorher vollständiges HA-Backup und separate Plan-/Einstellungssicherung; keine Geräte geschaltet. Aktuell bestehen <strong>26 Node- und acht Python-Tests</strong>. Bilder zeigen die deutsche Oberfläche.</p><p>Keine vollständige HA-Semantikprüfung im Editor: Ziele, Templates und Selektoren in HA kontrollieren. Kommentare, YAML-Anker und Formatierung werden nicht originalgetreu rekonstruiert. Importgrenzen: <strong>1 MB, 200 Bausteine, 500 Leitungen</strong>, begrenzte Verschachtelung und bis zu 250 Blueprint-Dateien in üblichen Ordnern. Regler, Kalender und eigene Unterpläne sind teilweise noch Vorlagen.</p><p>Für lokale Tests das Release-ZIP vollständig entpacken, Python 3.10+ und die Pakete aus <code>requirements.txt</code> installieren; unter Windows danach <strong>Start-Demo.cmd</strong> starten. <code>http://127.0.0.1:4180/</code> zeigt Demo-Entitäten ohne HA-Verbindung. Das ZIP enthält außerdem <code>addon/logic_studio/</code> für lokale App-Installationen.</p><p>Fehler bitte mit Versionen, Architektur und einem kleinen anonymisierten Beispiel <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">auf GitHub melden</a>. Keine Zugangsdaten, persönlichen Automationen oder Vollbackups veröffentlichen. Weitere Anleitungen und Prüfbericht liegen im Paket. Lizenz: MIT; Herkunft der übernommenen Block-Metadaten siehe <code>THIRD-PARTY.txt</code>.</p>',175)])])}const L=m(A,[["render",S]]);export{D as __pageData,L as default};
